1	<script lang="ts">
2		import { onMount, untrack } from 'svelte';
3		import { SvelteSet } from 'svelte/reactivity';
4		import { page } from '$app/stores';
5		import { goto } from '$app/navigation';
6		import { resolve } from '$app/paths';
7		import { supabase } from '$lib/supabaseClient';
8		import { getSignedReceiptUrls } from '$lib/utils/signedUrl';
9		import { ReceiptService } from '$lib/services/ReceiptService';
10		import { CategoryService } from '$lib/services/CategoryService';
11		import { ExpenseService } from '$lib/services/ExpenseService';
12		import type { ReceiptRow } from '$lib/models/Receipt';
13		import type { Category } from '$lib/types/Category';
14		import { buildCategoryMap } from '$lib/utils/resolveCategory';
15		import { detectDuplicates } from '$lib/utils/duplicateDetection';
16		import { getDuplicateInfo } from '$lib/utils/duplicateHelpers';
17		import {
18			readDateFilter,
19			matchesDateRange,
20			applyDateFilterParams,
21			clearDateFilterParams
22		} from '$lib/utils/sharedDateFilter';
23		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
24		import { Datepicker } from 'flowbite-svelte';
25		import {
26			toDate,
27			toISODateString,
28			dateOrRangeToDate,
29			formatDate
30		} from '$lib/utils/dateConversion';
31		import { formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
32		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
33		import FilterPanel from '$lib/components/FilterPanel.svelte';
34		import FilteredEmptyState from '$lib/components/FilteredEmptyState.svelte';
35		import DataTable from '$lib/components/DataTable.svelte';
36		import Notification from '$lib/components/Notification.svelte';
37		import { emptySelection } from '$lib/utils/selectionModel';
38		import {
39			newManualReceiptForm,
40			validateManualReceipt,
41			type ManualReceiptForm,
42			type ManualReceiptField
43		} from '$lib/utils/manualReceipt';
44	
45		const receiptService = new ReceiptService(supabase);
46	
47		let allReceipts: ReceiptRow[] = $state([]);
48		let error: string | null = $state(null);
49		let uploading = $state(false);
50		let manual = $state<ManualReceiptForm>(newManualReceiptForm());
51		let showManualForm = $state(false);
52		// Inline validation error for the manual-create form. `field` targets the
53		// offending input so the message renders next to it; 'form' is a general
54		// submit failure shown above the Create button.
55		let manualError: { field: ManualReceiptField | 'form'; message: string } | null = $state(null);
56		let deleting = new SvelteSet<string>();
57	
58		// #{#rct1b} Receipt edit modal state
59		let editingReceipt: ReceiptRow | null = $state(null);
60		let showEditModal = $state(false);
61		let isSavingReceipt = $state(false);
62		let editModalError: string | null = $state(null);
63	
64		// #{#rmc2a} Category state for ReceiptEditModal
65		let categories: Category[] = $state([]);
66		let familyId: string | null = $state(null);
67		let categoryMap: Record<string, Category | null> = $state({});
68	
69		// #{#blk1b} Selection state management (owned by <DataTable>)
70		let receiptSelection = $state(emptySelection());
71		let isDeleting = $state(false);
72		let successMessage: string | null = $state(null);
73		let errorMessage: string | null = $state(null);
74	
75		// #{#sdf2a} Read date filters from URL query parameters
76		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
77		let urlDateFrom = $derived(urlDateFilter.dateFrom);
78		let urlDateTo = $derived(urlDateFilter.dateTo);
79	
80		// Client-side filters - temporary values for inputs
81		let tempFilterDateFrom = $state(readDateFilter($page.url.searchParams).dateFrom);
82		let tempFilterDateTo = $state(readDateFilter($page.url.searchParams).dateTo);
83		let tempFilterMerchant = $state('');
84		let tempFilterAmountMin = $state('');
85		let tempFilterAmountMax = $state('');
86	
87		// Sync temp date values when URL changes
88		$effect(() => {
89			tempFilterDateFrom = urlDateFrom;
90			tempFilterDateTo = urlDateTo;
91		});
92	
93		// Active filter values used for filtering (non-date filters only)
94		let filterMerchant = $state('');
95		let filterAmountMin = $state('');
96		let filterAmountMax = $state('');
97	
98		// #{#dtv3a} Needs Review filter state
99		let filterNeedsReview = $state(false);
100	
101		// #{#dup5a} Duplicate receipts filter state
102		let filterDuplicates = $state(false);
103	
104		async function deleteReceipt(r: ReceiptRow): Promise<void> {
105			if (!confirm('Delete this receipt? This will remove the record and the stored file.')) return;
106			deleting.add(r.id);
107			error = null;
108			try {
109				await receiptService.delete(r.id, r.receipt_image_path);
110				allReceipts = allReceipts.filter((x) => x.id !== r.id);
111			} catch (e: unknown) {
112				error = e instanceof Error ? e.message : 'Failed to delete receipt';
113			} finally {
114				deleting.delete(r.id);
115			}
116		}
117	
118		async function load(): Promise<void> {
119			error = null;
120			try {
121				// DataTable sorts client-side over the full in-memory list; load in a stable order.
122				allReceipts = await receiptService.list('transaction_date', 'desc');
123			} catch (e: unknown) {
124				error = e instanceof Error ? e.message : 'Failed to load receipts';
125			}
126		}
127	
128		onMount(async () => {
129			await load();
130			await loadCategories();
131		});
132	
133		async function onFilesChanged(e: Event): Promise<void> {
134			const input = e.target as HTMLInputElement;
135			const files = input.files;
136			if (!files) return;
137			uploading = true;
138			error = null;
139	
140			// #{#dtv2a} Upload receipts — suspicious dates are silently flagged, no dialog shown
141			// Each file is processed independently so one failure doesn't abort the batch.
142			const failures: string[] = [];
143			for (const file of files) {
144				try {
145					const receipt = await receiptService.uploadAndCreate(file);
146					allReceipts = [receipt, ...allReceipts];
147				} catch (err: unknown) {
148					console.error('Failed to upload receipt', file.name, err);
149					failures.push(`${file.name}: ${err instanceof Error ? err.message : 'Failed to upload'}`);
150				}
151			}
152			if (failures.length > 0) {
153				error = `Failed ${failures.length} of ${files.length} receipt(s):\n${failures.join('\n')}`;
154			}
155			uploading = false;
156	
157			input.value = '';
158		}
159	
160		// #{#sec1a} Signed URL cache for receipt images
161		let signedUrls: Record<string, string> = $state({});
162	
163		// #{#sec1a} Load signed URLs whenever allReceipts changes
164		// Uses untrack to read signedUrls without creating a reactive loop
165		$effect(() => {
166			const paths = allReceipts.map((r) => r.receipt_image_path).filter((p): p is string => !!p);
167			untrack(() => loadSignedUrls(paths));
168		});
169	
170		async function loadSignedUrls(paths: string[]) {
171			const cached = signedUrls;
172			const newUrls: Record<string, string> = {};
173			const missing: string[] = [];
174			for (const path of paths) {
175				if (cached[path]) newUrls[path] = cached[path];
176				else missing.push(path);
177			}
178			// #{#sec1c} Sign all uncached paths in one batched request instead of one per path.
179			if (missing.length > 0) {
180				Object.assign(newUrls, await getSignedReceiptUrls(missing));
181			}
182			signedUrls = newUrls;
183		}
184	
185		function getImageUrl(path: string | null): string | null {
186			if (!path) return null;
187			return signedUrls[path] ?? null;
188		}
189	
190		// #{#rct1a} Open edit modal when row is clicked
191		function openEditModal(receipt: ReceiptRow) {
192			editingReceipt = { ...receipt };
193			showEditModal = true;
194			editModalError = null;
195		}
196	
197		// #{#rct4b} Close edit modal
198		function closeEditModal() {
199			showEditModal = false;
200			editingReceipt = null;
201			editModalError = null;
202			isSavingReceipt = false;
203		}
204	
205		// #{#rct5a} Save receipt changes from modal
206		async function handleSaveReceipt(updatedReceipt: ReceiptRow) {
207			isSavingReceipt = true;
208			editModalError = null;
209	
210			try {
211				const patch = {
212					merchant_name: updatedReceipt.merchant_name,
213					total_amount: updatedReceipt.total_amount,
214					transaction_date: updatedReceipt.transaction_date,
215					tax: updatedReceipt.tax,
216					currency: updatedReceipt.currency,
217					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
218					credit_card_name: updatedReceipt.credit_card_name,
219					credit_card_last_4: updatedReceipt.credit_card_last_4,
220					// #{#dtv2d} Preserve confirmed suspicious_date status
221					suspicious_date: updatedReceipt.suspicious_date
222				};
223	
224				const saved = await receiptService.update(updatedReceipt.id, patch);
225				allReceipts = allReceipts.map((r) => (r.id === saved.id ? saved : r));
226	
227				// #{#rct5b} Show success message
228				successMessage = 'Receipt updated successfully';
229				setTimeout(() => {
230					successMessage = null;
231				}, 3000);
232	
233				closeEditModal();
234			} catch (e: unknown) {
235				editModalError = e instanceof Error ? e.message : 'Failed to save receipt';
236			} finally {
237				isSavingReceipt = false;
238			}
239		}
240	
241		// #{#rmc2a} Load family categories for CategoryDropdown in edit modal
242		async function loadCategories() {
243			try {
244				familyId = await getDefaultFamilyId();
245				if (!familyId) return;
246	
247				const categoryService = new CategoryService(supabase);
248				categories = await categoryService.getFamilyCategories(familyId);
249	
250				// Load category assignments for all receipts (RF-09: shared resolver)
251				const expenseService = new ExpenseService(supabase);
252				const user = (await supabase.auth.getUser()).data.user;
253				if (user) {
254					const expenses = await expenseService.getExpenses(user.id);
255					categoryMap = buildCategoryMap(expenses, categories);
256				}
257			} catch (err) {
258				console.error('Error loading categories:', err);
259			}
260		}
261	
262		// #{#rmc2a} Handle category change from ReceiptEditModal
263		async function handleCategoryChange(receiptId: string, category: Category) {
264			if (!familyId) return;
265	
266			try {
267				const expenseService = new ExpenseService(supabase);
268				await expenseService.assignCategory(receiptId, category.id, 'manual');
269	
270				// Create vendor rule if none exists
271				const receipt = allReceipts.find((r) => r.id === receiptId);
272				if (receipt?.merchant_name) {
273					const existingRule = await expenseService.getVendorRule(familyId, receipt.merchant_name);
274					if (!existingRule) {
275						await expenseService.createVendorRule(familyId, receipt.merchant_name, category.id);
276					}
277				}
278	
279				// Update local category map
280				categoryMap = { ...categoryMap, [receiptId]: category };
281			} catch (err) {
282				console.error('Error assigning category:', err);
283			}
284		}
285	
286		async function createManual(e: Event): Promise<void> {
287			e.preventDefault();
288	
289			manualError = null;
290	
291			const validation = validateManualReceipt(manual);
292			if (!validation.ok) {
293				manualError = { field: validation.field, message: validation.message };
294				return;
295			}
296	
297			try {
298				const created = await receiptService.createManual(validation.value);
299				allReceipts = [created, ...allReceipts];
300				// Reset for the next entry — date defaults back to today; form stays expanded.
301				manual = newManualReceiptForm();
302				successMessage = `Receipt created: ${validation.value.merchant_name}`;
303				setTimeout(() => {
304					successMessage = null;
305				}, 3000);
306			} catch (err: unknown) {
307				manualError = {
308					field: 'form',
309					message: err instanceof Error ? err.message : 'Failed to create receipt'
310				};
311			}
312		}
313	
314		function applyClientFilters(rcts: ReceiptRow[]): ReceiptRow[] {
315			// #{#dup5a} Pre-compute duplicate IDs when filter is active
316			let dupeIds: Set<string> | null = null;
317			if (filterDuplicates) {
318				const dupes = detectDuplicates(rcts);
319				// eslint-disable-next-line svelte/prefer-svelte-reactivity -- local, non-reactive lookup set built and read within this call; SvelteSet would be inappropriate here
320				dupeIds = new Set<string>();
321				for (const ids of dupes.values()) {
322					for (const id of ids) dupeIds.add(id);
323				}
324			}
325	
326			return rcts.filter((r) => {
327				// #{#dtv3a} Filter by suspicious_date (Needs Review)
328				if (filterNeedsReview && !r.suspicious_date) return false;
329	
330				// #{#dup5a} Filter by duplicate status
331				if (filterDuplicates && dupeIds && !dupeIds.has(r.id)) return false;
332	
333				// #{#sdf1b} Filter by date range using URL parameters
334				if (!matchesDateRange(r.transaction_date, urlDateFrom, urlDateTo)) return false;
335	
336				// Filter by merchant name (local state)
337				if (filterMerchant) {
338					const merchantSearch = filterMerchant.toLowerCase();
339					const merchant = (r.merchant_name || '').toLowerCase();
340					if (!merchant.includes(merchantSearch)) return false;
341				}
342	
343				// Filter by amount range (local state)
344				if (filterAmountMin && r.total_amount !== null) {
345					const minAmount = parseFloat(filterAmountMin);
346					if (!isNaN(minAmount) && r.total_amount < minAmount) return false;
347				}
348				if (filterAmountMax && r.total_amount !== null) {
349					const maxAmount = parseFloat(filterAmountMax);
350					if (!isNaN(maxAmount) && r.total_amount > maxAmount) return false;
351				}
352	
353				return true;
354			});
355		}
356	
357		function applyFilterValues(): void {
358			// #{#sdf2a} Update URL with date filters
359			const params = applyDateFilterParams(
360				$page.url.searchParams,
361				tempFilterDateFrom,
362				tempFilterDateTo
363			);
364			goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });
365	
366			// Apply non-date filters locally
367			filterMerchant = tempFilterMerchant;
368			filterAmountMin = tempFilterAmountMin;
369			filterAmountMax = tempFilterAmountMax;
370		}
371	
372		function clearClientFilters(): void {
373			// #{#sdf2a} Clear URL date filters
374			const params = clearDateFilterParams($page.url.searchParams);
375			goto(resolve(`/receipts?${params.toString()}`), { replaceState: true, keepFocus: true });
376	
377			// Clear local filters
378			tempFilterMerchant = '';
379			tempFilterAmountMin = '';
380			tempFilterAmountMax = '';
381			filterMerchant = '';
382			filterAmountMin = '';
383			filterAmountMax = '';
384	
385			// #{#dtv3a} Clear Needs Review filter
386			filterNeedsReview = false;
387	
388			// #{#dup5a} Clear Duplicates filter
389			filterDuplicates = false;
390		}
391	
392		// applyClientFilters reads every filter variable (URL date range + local filters),
393		// so $derived tracks them all — no explicit dependency list needed.
394		let receipts = $derived(applyClientFilters(allReceipts));
395	
396		// #{#dup1b} #{#dup2b} Detect duplicates on filtered receipts
397		let duplicateGroups = $derived(detectDuplicates(receipts));
398	
399		// #{#dup5a} Detect duplicates on ALL receipts for badge count
400		let allDuplicateGroups = $derived(detectDuplicates(allReceipts));
401		let duplicateReceiptCount = $derived(
402			Array.from(allDuplicateGroups.values()).reduce((sum, ids) => sum + ids.length, 0)
403		);
404	
405		let hasActiveFilters = $derived(
406			urlDateFrom ||
407				urlDateTo ||
408				filterMerchant ||
409				filterAmountMin ||
410				filterAmountMax ||
411				filterNeedsReview ||
412				filterDuplicates
413		);
414	
415		// #{#blk4b} Clear selection
416		function clearSelection(): void {
417			receiptSelection = emptySelection();
418		}
419	
420		// #{#blk2a} #{#blk2b} #{#blk3a} #{#blk3b} Selection-based bulk delete
421		// (native confirm + optimistic update with rollback).
422		async function deleteSelected(): Promise<void> {
423			const idsToDelete = Array.from(receiptSelection.selected);
424			if (idsToDelete.length === 0) return;
425			if (
426				!confirm(
427					`Delete ${idsToDelete.length} selected receipt${idsToDelete.length === 1 ? '' : 's'}? This removes the record and the stored file.`
428				)
429			) {
430				return;
431			}
432	
433			isDeleting = true;
434			errorMessage = null;
435			successMessage = null;
436	
437			// #{#blk3b} Optimistic UI update
438			const originalReceipts = [...allReceipts];
439			allReceipts = allReceipts.filter((r) => !receiptSelection.selected.has(r.id));
440	
441			try {
442				// #{#blk3a} Call bulk delete service
443				await receiptService.bulkDeleteReceipts(idsToDelete);
444	
445				// #{#blk6b} Success feedback
446				successMessage = `Successfully deleted ${idsToDelete.length} receipt${idsToDelete.length === 1 ? '' : 's'}`;
447				clearSelection();
448				setTimeout(() => {
449					successMessage = null;
450				}, 4000);
451			} catch (e: unknown) {
452				// #{#blk3b} Rollback on failure
453				allReceipts = originalReceipts;
454				errorMessage =
455					e instanceof Error ? e.message : 'Failed to delete receipts. Please try again.';
456				setTimeout(() => {
457					errorMessage = null;
458				}, 8000);
459			} finally {
460				isDeleting = false;
461			}
462		}
463	
464		// #{#blk1b} Clear invalid selections when receipts are deleted individually
465		$effect(() => {
466			const validIds = new Set(allReceipts.map((r) => r.id));
467			const filtered = new Set(
468				Array.from(receiptSelection.selected).filter((id) => validIds.has(id))
469			);
470			if (filtered.size !== receiptSelection.selected.size) {
471				receiptSelection = { selected: filtered, anchorId: receiptSelection.anchorId };
472			}
473		});
474	</script>
475	
476	<svelte:head>
477		<title>Receipts</title>
478	</svelte:head>
479	
480	<div class="mb-6 flex items-start justify-between gap-4">
481		<div>
482			<h1 class="mb-2 text-2xl font-bold">Receipts</h1>
483			<p class="text-gray-600">Upload and manage your receipts.</p>
484		</div>
485		<label
486			class="inline-flex cursor-pointer items-center gap-2 rounded border bg-blue-600 px-4 py-2 text-sm text-white hover:bg-blue-700"
487		>
488			<input
489				class="hidden"
490				type="file"
491				multiple
492				onchange={onFilesChanged}
493				accept="image/jpeg,image/png,image/heic,application/pdf"
494			/>
495			{uploading ? 'Uploading…' : 'Upload receipts'}
496		</label>
497	</div>
498	
499	<!-- #{#blk6b} Success/Error notifications -->
500	{#if error}
501		<Notification type="error" message={error} onDismiss={() => (error = null)} />
502	{/if}
503	
504	{#if errorMessage}
505		<Notification type="error" message={errorMessage} onDismiss={() => (errorMessage = null)} />
506	{/if}
507	
508	{#if successMessage}
509		<Notification type="success" message={successMessage} onDismiss={() => (successMessage = null)} />
510	{/if}
511	
512	<!-- Filters -->
513	<FilterPanel
514		bind:dateFrom={tempFilterDateFrom}
515		bind:dateTo={tempFilterDateTo}
516		onApply={applyFilterValues}
517		onClear={clearClientFilters}
518		gridClass="grid grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-5"
519	>
520		{#snippet filters()}
521			<div>
522				<label for="rcpt-filter-merchant" class="mb-1 block text-sm font-medium">Merchant Name</label>
523				<input
524					id="rcpt-filter-merchant"
525					type="text"
526					bind:value={tempFilterMerchant}
527					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
528					placeholder="Search merchant..."
529				/>
530			</div>
531			<div>
532				<label for="rcpt-filter-amount-min" class="mb-1 block text-sm font-medium"
533					>Min Amount ($)</label
534				>
535				<input
536					id="rcpt-filter-amount-min"
537					type="number"
538					step="0.01"
539					bind:value={tempFilterAmountMin}
540					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
541					placeholder="Min"
542				/>
543			</div>
544			<div>
545				<label for="rcpt-filter-amount-max" class="mb-1 block text-sm font-medium"
546					>Max Amount ($)</label
547				>
548				<input
549					id="rcpt-filter-amount-max"
550					type="number"
551					step="0.01"
552					bind:value={tempFilterAmountMax}
553					class="w-full rounded border border-gray-300 px-3 py-2 text-sm"
554					placeholder="Max"
555				/>
556			</div>
557		{/snippet}
558		{#snippet secondary()}
559			<!-- #{#dtv3a} Needs Review filter toggle -->
560			<div class="mt-3">
561				<label class="inline-flex cursor-pointer items-center gap-2">
562					<input
563						type="checkbox"
564						bind:checked={filterNeedsReview}
565						class="h-4 w-4 rounded border-gray-300"
566						aria-label="Show only receipts needing date review"
567					/>
568					<span class="text-sm font-medium">
569						Show only receipts needing date review
570						{#if filterNeedsReview || allReceipts.some((r) => r.suspicious_date)}
571							<span
572								class="ml-2 inline-flex items-center gap-1 rounded-full bg-orange-100 px-2 py-0.5 text-xs font-semibold text-orange-800"
573								role="status"
574								aria-live="polite"
575							>
576								<svg
577									class="h-3 w-3"
578									fill="none"
579									stroke="currentColor"
580									viewBox="0 0 24 24"
581									aria-hidden="true"
582								>
583									<path
584										stroke-linecap="round"
585										stroke-linejoin="round"
586										stroke-width="2"
587										d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
588									/>
589								</svg>
590								{allReceipts.filter((r) => r.suspicious_date).length}
591							</span>
592						{/if}
593					</span>
594				</label>
595			</div>
596			<!-- #{#dup5a} Duplicate receipts filter -->
597			<div class="mt-3">
