3	/**
4	 * Detects duplicate receipts based on matching total_amount and transaction_date.
5	 *
6	 * Specifications implemented:
7	 * - #{#dup1b} Duplicate detection logic
8	 * - #{#dup3a} Performance optimization
9	 *
10	 * @param receipts - Array of receipts to analyze for duplicates
11	 * @returns Map where keys are composite keys (amount|date) and values are arrays of receipt IDs
12	 *          Only includes groups with 2+ receipts (actual duplicates)
13	 */
14	export function detectDuplicates(receipts: ReceiptRow[]): Map<string, string[]> {
15		const groups = new Map<string, string[]>();
16	
17		// Single pass through receipts - O(n) complexity
18		for (const receipt of receipts) {
19			// Skip receipts with null/undefined amount or date (#{#dup1b} requirement)
20			if (receipt.total_amount == null || !receipt.transaction_date) {
21				continue;
22			}
23	
24			// Create composite key from amount and date
25			const key = `${receipt.total_amount}|${receipt.transaction_date}`;
26	
27			// Get existing group or create new array
28			const existing = groups.get(key) || [];
29			existing.push(receipt.id);
30			groups.set(key, existing);
31		}
32	
33		// Filter out non-duplicates (groups with only 1 receipt)
34		const keysToDelete: string[] = [];
35		groups.forEach((ids, key) => {
36			if (ids.length < 2) {
37				keysToDelete.push(key);
38			}
39		});
40		keysToDelete.forEach((key) => groups.delete(key));
41	
42		return groups;
43	}
