import { describe, it, expect, vi } from 'vitest';
import { processUploadBatch } from './batchUpload';

/**
 * Unit tests for the per-file batch-upload orchestration (spec upr2a).
 *
 * The upload dependency is always injected, so these tests never touch storage or
 * OCR. They pin the isolation behaviour (one failure never aborts the batch) and
 * the exact error-summary message shape the receipts page renders.
 */

/** Build a minimal File with a given name; contents are irrelevant to the helper. */
function file(name: string): File {
	return new File(['x'], name);
}

describe('processUploadBatch', () => {
	it('processes every file and returns successes in file order when all succeed', async () => {
		const files = [file('a.jpg'), file('b.jpg'), file('c.jpg')];
		const uploadOne = vi.fn((f: File) => Promise.resolve(`ok:${f.name}`));

		const result = await processUploadBatch(files, uploadOne);

		expect(uploadOne).toHaveBeenCalledTimes(3);
		expect(result.successes).toEqual(['ok:a.jpg', 'ok:b.jpg', 'ok:c.jpg']);
		expect(result.failures).toEqual([]);
		expect(result.errorMessage).toBeNull();
	});

	it('calls onSuccess for each file in order', async () => {
		const files = [file('a.jpg'), file('b.jpg')];
		const seen: string[] = [];

		await processUploadBatch(files, (f) => Promise.resolve(f.name), {
			onSuccess: (result, f) => seen.push(`${result}<-${f.name}`)
		});

		expect(seen).toEqual(['a.jpg<-a.jpg', 'b.jpg<-b.jpg']);
	});

	it('isolates a single failure so the remaining files still process', async () => {
		const files = [file('a.jpg'), file('bad.jpg'), file('c.jpg')];
		const uploadOne = vi.fn((f: File) =>
			f.name === 'bad.jpg' ? Promise.reject(new Error('boom')) : Promise.resolve(f.name)
		);

		const result = await processUploadBatch(files, uploadOne);

		expect(uploadOne).toHaveBeenCalledTimes(3);
		expect(result.successes).toEqual(['a.jpg', 'c.jpg']);
		expect(result.failures).toEqual(['bad.jpg: boom']);
		expect(result.errorMessage).toBe('Failed 1 of 3 receipt(s):\nbad.jpg: boom');
	});

	it('invokes onError with the failing file and thrown value', async () => {
		const files = [file('bad.jpg')];
		const err = new Error('boom');
		const onError = vi.fn();

		await processUploadBatch(files, () => Promise.reject(err), { onError });

		expect(onError).toHaveBeenCalledTimes(1);
		expect(onError).toHaveBeenCalledWith(files[0], err);
	});

	it('aggregates multiple failures into the multi-line summary', async () => {
		const files = [file('a.jpg'), file('b.jpg'), file('c.jpg')];
		const uploadOne = (f: File) => Promise.reject(new Error(`fail ${f.name}`));

		const result = await processUploadBatch(files, uploadOne);

		expect(result.successes).toEqual([]);
		expect(result.failures).toEqual([
			'a.jpg: fail a.jpg',
			'b.jpg: fail b.jpg',
			'c.jpg: fail c.jpg'
		]);
		expect(result.errorMessage).toBe(
			'Failed 3 of 3 receipt(s):\na.jpg: fail a.jpg\nb.jpg: fail b.jpg\nc.jpg: fail c.jpg'
		);
	});

	it('falls back to a generic reason when the thrown value is not an Error', async () => {
		const files = [file('a.jpg')];

		const result = await processUploadBatch(files, () => Promise.reject('not-an-error'));

		expect(result.failures).toEqual(['a.jpg: Failed to upload']);
		expect(result.errorMessage).toBe('Failed 1 of 1 receipt(s):\na.jpg: Failed to upload');
	});

	it('returns an empty, no-error result for an empty file list', async () => {
		const uploadOne = vi.fn(() => Promise.resolve('ok'));

		const result = await processUploadBatch([], uploadOne);

		expect(uploadOne).not.toHaveBeenCalled();
		expect(result.successes).toEqual([]);
		expect(result.failures).toEqual([]);
		expect(result.errorMessage).toBeNull();
	});
});
